create temp table vend as select v, gen_random_uuid() as user_id from (select distinct v from forma) z;
create temp table con as
  select row_number() over () as n, gen_random_uuid() as id, d.user_id, f.*
    from forma f join vend d using (v);
insert into public.bank_connections (id, user_id, item_id, institution_name, status, papel, papel_desde, papel_auto)
select id, user_id, 'item-' || n, 'Banco ' || n, case when del then 'deleted' else 'UPDATED' end, papel,
       case when dias is not null then now() - make_interval(days => dias) end, auto
  from con;
insert into public.bank_saldos (conta_id, user_id, bank_connection_id, banco, nome, saldo)
select 'acc-' || c.n || '-' || g, c.user_id, c.id, 'Banco ' || c.n, 'Conta ' || g, 0
  from con c cross join lateral generate_series(1, c.contas) g;

select public.of_espelho_atualizar() as r \gset

select t.igual('143 conexoes viram 143 vinculos', (select count(*) from public.of_vinculos)::numeric, 143);
select t.igual('60 ativos', (select count(*) from public.of_vinculos where estado = 'ativo')::numeric, 60);
select t.igual('83 removidos', (select count(*) from public.of_vinculos where estado = 'removido')::numeric, 83);
select t.igual('112 linhas de saldo viram 112 contas, nenhuma fundida', (select count(*) from public.of_contas)::numeric, 112);
select t.igual('formato de producao: divergencia zero na regra de conta de venda', (select count(*) from public.of_espelho_conferir())::numeric, 0);
select t.igual('...tambem perguntando por um instante de 45 dias atras', (select count(*) from public.of_espelho_conferir(now() - interval '45 days'))::numeric, 0);
select t.igual('nenhum registro incompleto, conflito ou problema', ((:'r'::jsonb ->> 'registros_incompletos')::int + (:'r'::jsonb ->> 'conflitos')::int + (:'r'::jsonb ->> 'problemas')::int)::numeric, 0);
select t.igual('a regra atual e o espelho dizem "conta de venda" para as mesmas conexoes',
  (select count(*) from public.of_vinculos v where public.of_vinculo_conta_de_venda(v.id, now()))::numeric,
  (select count(*) from public.bank_connections b where public.banco_conta_de_venda(b.id, now()))::numeric);
